// "Load vanilla template" — fetches the bundled manifest of shipped origins
// and classes (generated by `scripts/gen-vanilla-templates.ts`) and turns a
// chosen entry into an editable `OriginDraft`.
//
// We reuse the datapack importer's `buildDraft` rather than re-implementing
// the body→draft mapping: each entry is reconstituted into the same in-memory
// file map a real datapack import produces, then handed to `buildDraft`. So a
// templated origin keeps its source `neoorigins:` id — saving/exporting writes
// a direct override of the shipped origin, which is the whole point.
//
// `tier_powers` (evolution) has no editor UI; it rides through `extras` and is
// exported as it was, naming the shipped tier powers, so the tiers survive.

import { base } from '$app/paths';

import { ImportError } from './import';

/** One selectable template (the picker's view — body/powers omitted). */
export interface TemplateEntry {
	id: string;
	localId: string;
	name: string;
	isClass: boolean;
	icon: string | null;
	impact: string;
	layerPath: string;
	tierPowerCount: number;
	originBody: Record<string, unknown>;
	powers: Record<string, string>;
}

export interface TemplateManifest {
	generatedFrom: string;
	namespace: string;
	packFormat: number;
	entries: TemplateEntry[];
}

let cache: Promise<TemplateManifest> | null = null;

/** Fetch (and memoize) the vanilla-template manifest from static assets. */
export function loadTemplateIndex(): Promise<TemplateManifest> {
	if (!cache) {
		cache = fetch(`${base}/vanilla-templates.json`).then((res) => {
			if (!res.ok) throw new Error(`vanilla-templates.json → HTTP ${res.status}`);
			return res.json() as Promise<TemplateManifest>;
		});
		// Don't cache a rejected fetch — let the next call retry.
		cache.catch(() => {
			cache = null;
		});
	}
	return cache;
}

export { loadTemplate } from './templateDraft';

export { ImportError };
